/* Bandora original fictional IELTS-style practice. This is not an official examination. */
(function () {
  'use strict';
  const bank = {};
  function add(number, title, definitions) {
    const parts = definitions.map((d, index) => ({
      title:d[0],
      description:`Part ${index + 1}. Choose ONE answer for multiple-choice questions. For completion questions, write no more than TWO WORDS AND/OR A NUMBER.`,
      transcript:[d[1], ...d[2].map(r => r[0]), d[3]].join('\n\n'),
      questions:d[2].map((r, i) => ({id:index * 10 + i + 1, type:r[4] ? 'mcq' : 'text', prompt:r[1], answer:r[2], explanation:r[3], ...(r[4] ? {options:r[4]} : {}), ...(r[5] ? {acceptedAnswers:r[5]} : {})}))
    }));
    bank[number] = {title:`Ticket ${String(number).padStart(2, '0')} · Listening: ${title}`, duration:1800, parts, questions:parts.flatMap(p => p.questions), transcript:parts.map((p,i) => `PART ${i + 1} — ${p.title}\n\n${p.transcript}`).join('\n\n')};
  }
  add(5, 'Making, moving and measuring', [
    ['Joining a furniture workshop', `Adviser: Good afternoon, Willow Workshop. How can I help?
Caller: I have moved into a small flat and would like to make a table. I have repaired chairs at home, but I have never attended a practical course.
Adviser: We offer several courses. Let me find one that matches your experience and explain what you need to bring.`, [
      [`Caller: I saw an advertisement for a weekend course in cabinet making. Would that be suitable?
Adviser: That assumes you can already cut joints accurately. I recommend our beginners' furniture course instead. You will make a small bedside table, and the tutor demonstrates each technique before you try it yourself.`, 'The recommended course produces a small ______ table.', 'bedside', 'Beginners make a bedside table; the cabinet-making course is for more experienced learners.'],
      [`Caller: When does the next course begin? I am away on the first weekend next month.
Adviser: It starts on the nineteenth of November and runs on three consecutive Saturdays. We moved it from the twelfth because the tutor will be attending a trade exhibition that weekend.`, 'The course starts on ______ November.', '19', 'The confirmed start date is the nineteenth, rather than the original twelfth.', null, ['19th', 'nineteenth']],
      [`Adviser: Sessions run from nine thirty until four, with a break for lunch. The workshop opens at nine so people can settle in, but teaching does not begin until half past.
Caller: That gives me time to arrive by train. I will aim to be there a little early.`, 'Teaching begins at ______ each morning.', '9:30', 'The workshop opens at nine, but the course begins at nine thirty.', null, ['9.30', 'nine thirty', '09:30']],
      [`Caller: What does the course cost? The advertisement mentioned a hundred and sixty pounds.
Adviser: That was last year's price. It is now a hundred and eighty pounds, including timber and all shared tools. You will not need to purchase an expensive kit before discovering whether you enjoy woodworking.`, 'The current course fee is £______.', '180', 'The current fee is one hundred and eighty pounds, including timber and shared tools.', null, ['180.00']],
      [`Caller: Do I need protective equipment?
Adviser: We supply safety glasses and ear protection. Bring an apron if you have one; otherwise old clothing will do. What you must wear is closed shoes. Sandals are unsuitable because pieces of timber or small tools could fall onto your feet.`, 'Participants must wear ______.', 'closed shoes', 'Closed shoes are compulsory; an apron is optional.'],
      [`Caller: Is lunch available at the workshop?
Adviser: There is a café across the road, but it becomes crowded on Saturdays. Most learners bring a packed lunch and eat in our courtyard. There is a refrigerator for food, though please label anything you put in it because staff use it too.`, 'Most learners bring a ______.', 'packed lunch', 'Most participants bring a packed lunch rather than relying on the busy café.'],
      [`Caller: Can someone collect the finished table by car?
Adviser: Certainly. Ask them to use the side gate on Birch Street. The address on our website is Oak Road, but that entrance has steps. Birch Street gives level access to the loading area, which is much easier when carrying furniture.`, 'Collection by car is through the gate on ______ Street.', 'Birch', 'Birch Street provides level access for collecting furniture.'],
      [`Adviser: To reserve a place, we require a deposit of forty pounds. The remaining balance is due a week before the course begins. Your place is provisional until we receive the deposit, so sending the form alone does not guarantee that a space will be held indefinitely.
Caller: Understood.`, 'The deposit needed to reserve a place is £______.', '40', 'A forty-pound deposit confirms the reservation.', null, ['forty', '40.00']],
      [`Caller: I have an idea for a table with a shelf underneath. Can I discuss it beforehand?
Adviser: Yes, send a sketch with your form. A photograph of another table can be useful, but a sketch showing your own measurements is better. Keep the overall dimensions within our published limits.`, 'The adviser recommends sending a ______ showing the proposed measurements.', 'sketch', 'A measured sketch is preferred to a photograph of someone else’s table.'],
      [`Caller: I would also like to ask about suitable finishes for a child's bedroom.
Adviser: Our tutor, Mara, can advise you. She handles course questions on Thursday afternoons. Telephone then rather than during a class, when she will be supervising machinery and cannot leave the group to discuss individual projects.`, 'The tutor answers course questions on ______ afternoons.', 'Thursday', 'Mara handles these questions on Thursday afternoons.']
    ], `Caller: Thank you. I will complete the form tonight and include a sketch. I will call on Thursday if I have any remaining questions.
Adviser: Excellent. Once payment arrives, we will send written confirmation and directions to the workshop.`],
    ['A new town walking trail', `Welcome to the opening of the River and Railway Trail. I am the volunteer coordinator, and before you set off I will explain how the route works. The trail follows public paths through the town, linking places that are often passed without a second glance. You can complete it at your own pace rather than staying with a guided group.`, [
      [`The complete route is six kilometres long. Our first design covered eight kilometres, but that included an awkward stretch beside a busy road. We shortened it after consulting residents. If you walk steadily, allow about two hours; stopping to read every panel or visit the café will obviously take longer.`, 'The complete walking route is ______ kilometres long.', '6', 'The revised route is six kilometres; eight was the earlier proposal.', null, ['six']],
      [`Your starting point is the old courthouse, where we are standing now. The railway station would seem a natural beginning, but the pavement there is too narrow for groups. The courthouse has a sheltered forecourt, toilets and a drinking fountain, making it a much better place to prepare for a walk.`, 'The trail begins at the old ______.', 'courthouse', 'The courthouse is the start, chosen for its facilities and space.'],
      [`To follow the route, look for the blue arrows attached to existing signposts. Green arrows belong to a separate cycle route, and yellow markers indicate temporary diversions for roadworks. Our blue markers include a small river symbol, so they remain recognisable even when the colour has faded in strong sunlight.`, 'The trail is marked by ______ arrows.', 'blue', 'Blue arrows with a river symbol identify the walking trail.'],
      [`At the first riverside stop you will see a reconstructed loading platform. The original structure served the grain trade, although the neighbouring buildings later became textile warehouses. The interpretation panel explains how sacks were transferred between carts and barges without blocking the narrow road that ran behind the warehouses.`, 'The original loading platform was used for the ______ trade.', 'grain', 'The platform originally supported grain transport; textile warehouses came later.'],
      [`Beyond the platform, the normal route crosses a footbridge. Repairs begin next Monday, so for the following fortnight walkers must use the crossing beside the swimming pool. It adds only a few minutes. Please do not climb the barriers even if the bridge appears quiet; repairs will also be taking place underneath it.`, 'During bridge repairs, walkers should use the crossing beside the ______.', 'swimming pool', 'The temporary crossing is beside the swimming pool.'],
      [`Families can collect an activity booklet from the volunteer desk here. It asks children to find shapes and details rather than compete to finish first. We deliberately omitted timed challenges, because we want children to notice their surroundings and avoid running across entrances or missing traffic while watching a clock.`, 'Why were timed challenges left out of the children’s booklet?', 'To encourage careful observation', 'The speaker says children should notice their surroundings instead of competing to finish quickly.', ['To reduce printing costs', 'To encourage careful observation', 'To make the route shorter']],
      [`The former signal box is open on Sunday afternoons. It contains the original levers, but visitors must view them from behind a barrier. A retired railway worker demonstrates a model mechanism instead, which shows what happened along the track without requiring anyone to move the heavy equipment inside the actual building.`, 'The former signal box opens on ______ afternoons.', 'Sunday', 'The signal box is open on Sunday afternoons.'],
      [`For anyone who needs a rest, there are benches near the orchard halfway round. This is also the quietest picnic location. The square by the café has more seating, but delivery vehicles use it until lunchtime. Please take picnic rubbish home because the orchard bins are small and collected only twice a week.`, 'The quietest picnic location is near the ______.', 'orchard', 'The orchard is recommended for a quiet picnic rather than the delivery area by the café.'],
      [`We would welcome feedback after your walk, particularly about the directions. Several people have already sent us historical photographs, and our archive volunteers are cataloguing those. At this stage, however, knowing where a sign is confusing or hard to see will help us improve the everyday experience most quickly.`, 'What feedback is the coordinator especially requesting now?', 'Comments about route directions', 'The immediate priority is identifying unclear or poorly visible signs.', ['More historical photographs', 'Suggestions for café menus', 'Comments about route directions']],
      [`Finally, the free paper map is available in large print as well as the standard edition. Ask at the desk before leaving; we cannot store copies in the outdoor leaflet boxes because rain gets in. A downloadable version is also available, but you will not need a phone connection to follow the signs.`, 'A ______ version of the paper map is available at the desk.', 'large print', 'Large-print paper maps are available from the volunteer desk.']
    ], `That is everything you need to begin. Volunteers wearing silver badges will remain here until three, and an emergency contact number is printed on the map. Please leave gates as you find them and respect the gardens beside the path. We hope the walk gives familiar streets a different meaning.`],
    ['Evaluating a campus refill scheme', `Tutor: Tell me how your evaluation of the drinking-water refill scheme is progressing.
Nadia: We have completed the first observations, but our results were more uneven than expected.
Owen: We wanted to check our interpretation before writing the report. It would be easy to assume that a quiet refill station means students do not want to use it.
Tutor: Good. Start with your research question.`, [
      [`Nadia: Originally we planned to calculate how many plastic bottles the scheme had prevented from being sold.
Owen: We could not obtain reliable shop sales data, so we changed the question. We are now comparing how the location of a station affects its use.
Tutor: That is narrower and more manageable with the information you can collect.`, 'What is the revised main focus of the study?', 'The effect of station location', 'The students changed from estimating avoided bottle sales to comparing station locations.', ['The cost of bottled drinks', 'The effect of station location', 'Students’ preferred water temperature']],
      [`Owen: We watched each station for twenty minutes during the first trial.
Nadia: That missed the surge between lectures. For the main observations we used forty-minute periods, beginning ten minutes before classes ended.
Tutor: Keep those observation windows consistent. Otherwise one station might appear busier simply because you watched it at a more favourable time.`, 'Each main observation period lasted ______ minutes.', '40', 'Forty-minute periods replaced the twenty-minute trial periods.', null, ['forty']],
      [`Nadia: The library station had a queue at lunchtime, yet the nearby entrance station was almost unused.
Owen: We initially thought the entrance water tasted different, but both are supplied by the same system.
Nadia: Then we noticed that a temporary exhibition board blocked the entrance station from the main corridor.
Tutor: That is a plausible explanation worth testing.`, 'What probably explains the low use of the entrance station?', 'It was difficult to see', 'An exhibition board obscured the station; there was no evidence of different water quality.', ['It was difficult to see', 'Its water was too warm', 'It charged a small fee']],
      [`Owen: We also asked users why they chose a particular station. Several interviews were very brief because people were hurrying to lectures.
Tutor: What will you do about that?
Nadia: Offer a short questionnaire through a QR code, so users can answer later. We will still explain what the study is about before inviting them to participate.`, 'Users will access the follow-up questionnaire through a ______.', 'QR code', 'A QR code will let users complete the questionnaire later.'],
      [`Tutor: Did you record the people who walked past without stopping?
Owen: Only on the second day. We had counted refills but not the total passing traffic.
Nadia: That meant we could not distinguish an unpopular station from one in a rarely used corridor.
Tutor: Exactly. Your comparison should use the proportion of passers-by who stop, as well as raw refill counts.`, 'Which missing measure weakened the first day’s observations?', 'The number of passers-by', 'Without passing traffic, low refill counts could simply reflect a quiet corridor.', ['The price of reusable bottles', 'The number of passers-by', 'The length of each lecture']],
      [`Nadia: We made a separate note whenever someone abandoned the queue.
Owen: We agreed that this meant approaching the station, waiting, and then leaving without filling a bottle. Simply looking towards it did not count.
Tutor: Include that definition in your methods section. Readers need to know that both observers recorded the same behaviour in the same way.`, 'The methods section will define when a person has abandoned the ______.', 'queue', 'The students defined queue abandonment consistently for both observers.'],
      [`Owen: We disagree about adding signs above the least-used stations before our final observation.
Nadia: I think it would make the project more useful.
Tutor: It could, but first collect the full baseline under existing conditions. If you change the signs halfway through, you will no longer be comparing the original locations on an equal basis.`, 'What does the tutor advise about adding signs?', 'Complete the baseline observations first', 'Changing signage before the baseline is complete would undermine the original comparison.', ['Put signs at every station immediately', 'Complete the baseline observations first', 'Abandon the idea permanently']],
      [`Nadia: We can present the locations on a campus map, with circles showing how frequently each station is used.
Owen: I thought of a photograph of every station instead.
Tutor: The map will show their relationship to lecture halls and entrances more clearly. Photographs could go in an appendix if they illustrate obstructions or accessibility problems.`, 'The main visual presentation of station locations will be a campus ______.', 'map', 'A campus map will show the stations’ relationship to key buildings.'],
      [`Tutor: Be careful with the conclusion. Your observations cover one teaching week in mild weather.
Nadia: So we should not claim the pattern is identical during examinations or hot weather.
Owen: We can recommend repeating the study at a different time of year.
Tutor: Yes. A clear account of the limits makes a small study more convincing, not less.`, 'What limitation should the conclusion emphasise?', 'The short observation period', 'The study covers only one week and may not represent other seasons or examination periods.', ['The short observation period', 'The absence of any refill stations', 'The use of two observers']],
      [`Owen: When should we send you the draft? The written deadline is the twenty-eighth.
Tutor: Send the draft by the twenty-first if you want feedback before submission. I need a few days to read it, and you need time to revise.
Nadia: We will finish the charts first and send the complete draft on that date.`, 'The students should send their draft by the ______.', '21st', 'The tutor requests the draft by the twenty-first, before the final deadline on the twenty-eighth.', null, ['21', 'twenty-first', 'twenty first']]
    ], `Tutor: That sounds realistic. Keep the distinction between what you observed and what you infer from it. You can suggest explanations, but mark them as suggestions unless you have tested them.
Nadia: We will make that distinction explicit.
Owen: And we will add the passing-traffic figures to our comparison.`],
    ['Studying sound in historic buildings', `Today I will describe how researchers investigate the sound of historic buildings. The examples come from a fictional study designed to illustrate the method. A building's acoustics can reveal how people used it, but measurements alone cannot tell us exactly what a ceremony or conversation sounded like centuries ago. We need to combine physical evidence with careful interpretation.`, [
      [`The team began with a survey of a disused assembly hall. Before bringing in recording equipment, they produced a detailed floor plan. This recorded the dimensions, the position of doors and the surviving wall surfaces. Such a plan allows later measurements to be compared and helps identify features that might redirect sound.`, 'The researchers first produced a detailed ______.', 'floor plan', 'A detailed floor plan was prepared before acoustic recording began.'],
      [`Their main measurement was reverberation time: how long a sound persists after its source stops. A long reverberation can enrich a sustained musical note, yet blur a rapid sequence of spoken words. Therefore, describing a room as acoustically good is incomplete unless we specify the activity for which it is being assessed.`, 'The time for sound to persist after its source stops is called ______ time.', 'reverberation', 'Reverberation time measures the persistence of sound after the source stops.'],
      [`To make comparisons reliable, the researchers used the same loudspeaker at each source position. It played a controlled test signal rather than a musical performance. A performance would introduce differences in volume and timing, making it difficult to decide whether changes in the recording came from the room or from the performer.`, 'A controlled test signal was played through the same ______.', 'loudspeaker', 'A consistent loudspeaker and test signal reduced variation in the sound source.'],
      [`Microphones were placed at different heights to represent seated and standing listeners. Keeping every microphone at one height would have been simpler, but the hall had accommodated both meetings and processions. The researchers wanted to explore whether a person sitting near the rear experienced the same clarity as someone standing closer to the centre.`, 'Microphone heights represented listeners who were seated or ______.', 'standing', 'The two listening positions represented seated and standing people.'],
      [`A major difficulty was traffic outside the building. Even with the windows closed, low-frequency noise entered through gaps around the doors. The team consequently made the most sensitive recordings before sunrise, when fewer vehicles used the road. They also logged background noise so unsuitable recordings could be identified rather than silently included.`, 'The most sensitive recordings were made before ______.', 'sunrise', 'Recording before sunrise reduced interference from road traffic.'],
      [`The empty hall did not represent its historical condition. Documents described heavy curtains along one wall, although none survive. The researchers tested temporary fabric panels to estimate the possible effect. These absorbed some reflected sound, but the team reported a range of results because the weight and arrangement of the original curtains were uncertain.`, 'Temporary fabric panels were used to investigate the possible effect of historical ______.', 'curtains', 'Documents mentioned curtains, so fabric panels tested their possible acoustic effect.'],
      [`An audience also changes a room's acoustics because clothing and bodies absorb sound. Rather than recruit hundreds of volunteers for every trial, the team used a computer model to explore different audience sizes. A smaller volunteer session then helped them check whether the model's broad predictions were consistent with actual measurements.`, 'Different audience sizes were first explored using a computer ______.', 'model', 'The computer model explored audience size before a smaller volunteer validation session.'],
      [`One surprising finding concerned the wooden balcony. The researchers had expected it mainly to create echoes, but the measurements suggested that its underside redirected useful early reflections towards the rear seats. They did not conclude that the balcony's builders understood modern acoustic theory; a useful effect does not prove a particular design intention.`, 'What caution did the team express about the balcony?', 'Its useful effect did not prove deliberate acoustic design', 'The team distinguished a beneficial measured effect from evidence of the builders’ intentions.', ['It could not affect sound at all', 'Its useful effect did not prove deliberate acoustic design', 'It had to be removed before testing']],
      [`For the public exhibition, the team prepared pairs of short recordings. Visitors could compare the untreated room with a simulation including curtains and an audience. Each simulation was labelled as a reconstruction. This was important because a persuasive listening experience can easily be mistaken for a direct recording of the past, which it plainly is not.`, 'Each simulated recording was labelled as a ______.', 'reconstruction', 'The label made clear that the audio was an interpretation rather than an authentic historical recording.'],
      [`The final report recommended preserving the hall's existing surfaces until further work was complete. Replacing old plaster with modern panels might improve speech clarity, but it would also alter evidence that future researchers could study. The team therefore proposed reversible temporary treatments for events rather than immediate permanent changes to the historic interior.`, 'For events, the report proposed treatments that were temporary and ______.', 'reversible', 'Reversible temporary treatments could support events while preserving the historic surfaces.']
    ], `This example shows why acoustic history is an interdisciplinary activity. Measurement tells us what a surviving space does under specified conditions. Documents suggest how those conditions may once have differed. Responsible interpretation keeps the two forms of evidence connected while acknowledging where uncertainty remains.`]
  ]);
  add(6, 'Arrangements, access and adaptation', [
    ['Arranging short-term storage', `Agent: Good morning, Northbank Storage. This is Ellis speaking.
Customer: Hello. I am moving out of my flat before my new home is ready, so I need somewhere to keep furniture for about a month.
Agent: We can help with that. I will ask a few questions about the items and explain the practical arrangements.`, [
      [`Agent: Are you storing the contents of the whole flat?
Customer: Just the living room furniture and some boxes. My bed is going to my sister's house.
Agent: In that case, our medium unit should be sufficient. The small unit is mainly intended for boxes and would leave little room to move around larger furniture.`, 'The agent recommends a ______ unit.', 'medium', 'A medium unit is suitable for the furniture and boxes; the small unit is mainly for boxes.'],
      [`Customer: How much would a medium unit cost for four weeks?
Agent: The weekly rate is twenty-eight pounds, so four weeks would be a hundred and twelve pounds. We charge for complete weeks, but there is no requirement to book a full calendar month. That is useful when moving dates are uncertain.`, 'The weekly price is £______.', '28', 'The unit costs twenty-eight pounds per week.', null, ['28.00', 'twenty-eight', 'twenty eight']],
      [`Agent: When would you like the storage period to start?
Customer: I leave my flat on the eighth, but the removal company can bring everything on the seventh of March.
Agent: I will enter the seventh. Access begins that morning, and you can bring additional boxes yourself later if necessary.`, 'The storage period will begin on ______ March.', '7', 'The removal company will deliver on the seventh, one day before the customer leaves the flat.', null, ['7th', 'seventh']],
      [`Customer: Can I use my own padlock? I already have one from a garden shed.
Agent: You can, provided it is a closed-shackle lock. Ordinary long-shackle locks are not permitted under our security policy. We sell suitable locks at reception, but you are welcome to buy one elsewhere before you arrive.`, 'The unit requires a ______ lock.', 'closed-shackle', 'A closed-shackle lock is required; an ordinary long-shackle lock is unsuitable.', null, ['closed shackle']],
      [`Customer: What documents should I bring on the first day?
Agent: Bring photo identification and a recent utility bill showing your home address. If the bill is electronic, showing the original document on your phone is fine. A delivery label does not meet the address requirement because it does not confirm who holds the account.`, 'Proof of address should be a recent ______.', 'utility bill', 'A recent utility bill is required as proof of address.'],
      [`Customer: Is there somewhere the removal van can stop while we unload?
Agent: Yes, use loading bay three. Bay one is reserved for incoming commercial deliveries, and bay two is undergoing repairs. There are signs from the main gate, so the driver will not need to reverse through the customer car park.`, 'The removal van should use loading bay ______.', '3', 'Bay three is available for the customer’s removal van.', null, ['three']],
      [`Customer: Will I need to carry the boxes a long distance?
Agent: Your unit is on the first floor, but there is a goods lift beside the loading area. Trolleys are free to borrow. Please return them immediately after unloading, since other customers may be waiting and we have only a limited number.`, 'Customers can borrow ______ free of charge for moving boxes.', 'trolleys', 'Trolleys are available free of charge and should be returned after unloading.', null, ['trolley']],
      [`Customer: I occasionally work late. Can I visit in the evening?
Agent: Customer access ends at nine every evening. Reception closes at six, but your personal access code will operate the gate until nine. After that the alarm system changes mode, so you must finish and leave before the access period ends.`, 'Evening access ends at ______.', '9 pm', 'The gate remains available until nine in the evening, although reception closes at six.', null, ['9', 'nine', '21:00', '21.00', '9:00', '9.00']],
      [`Agent: One further point: we cannot store food, including unopened packets. It can attract pests, and smells may affect neighbouring units.
Customer: I was going to pack kitchen cupboards into a few boxes. I will check them carefully and give the food away before the removal company arrives.`, 'Customers must not put ______ in storage.', 'food', 'Food is prohibited even when packets are unopened.'],
      [`Customer: How much notice must I give before collecting everything?
Agent: Forty-eight hours, please. Email us rather than leaving a voicemail so we have a written record of your departure date. We can then prepare the final account and make sure there is space available for your van when you arrive.`, 'The customer should give ______ hours’ notice before collection.', '48', 'Forty-eight hours’ notice is required by email.', null, ['forty-eight', 'forty eight']]
    ], `Customer: That sounds straightforward. Please send the booking details to my email address, and I will check the lock before moving day.
Agent: Certainly. The message will include a map, the access agreement and a checklist to help you prepare your belongings.`],
    ['Visiting the Ridge Planetarium', `Welcome to the Ridge Planetarium. Before your school group enters, I will explain today's programme and a few features of the building. We have changed the order of activities this term so that pupils first explore some ideas themselves, then use the dome presentation to connect what they have discovered. Please keep your group together while moving between rooms.`, [
      [`Your first activity takes place in the discovery room, immediately opposite reception. You may remember starting in the dome on previous visits, but the discovery room now introduces the equipment and vocabulary. Pupils can handle model planets and compare scales before seeing images that may otherwise seem impressive but difficult to interpret.`, 'The first activity is in the ______ room.', 'discovery', 'The visit now starts in the discovery room rather than the dome.'],
      [`The dome presentation begins at eleven fifteen. Please arrive at the door five minutes earlier so everyone can be seated before the lights dim. Late arrivals cannot enter during the presentation because opening the door affects the projected sky and makes it difficult for people already seated to maintain their night vision.`, 'The dome presentation begins at ______.', '11:15', 'The presentation starts at eleven fifteen; pupils should reach the door five minutes earlier.', null, ['11.15', 'eleven fifteen']],
      [`For today's show we recommend the central seats. Those near the entrance are convenient for anyone who may need to leave, but the central section offers the most comfortable view of the overhead images. There is no front row in the usual cinema sense, since the projection surrounds the audience rather than appearing on a flat wall.`, 'Which seats are recommended for the most comfortable view?', 'Seats in the centre', 'Central seats provide the most comfortable view of the overhead images.', ['Seats beside the entrance', 'Seats in the centre', 'Seats against the back wall']],
      [`After the show, pupils will work in pairs on a navigation challenge. Each pair receives a compass and a printed sky chart. The chart is deliberately simplified: it shows a small number of recognisable patterns rather than every visible star, helping beginners locate useful reference points without being overwhelmed by detail.`, 'Each pair receives a sky chart and a ______.', 'compass', 'A compass and a simplified printed sky chart are supplied for the challenge.'],
      [`Your packed lunches can be eaten in the covered terrace at the east end of the building. The garden is attractive, but a maintenance team is repairing its paths today. The terrace remains dry in rain and has enough benches for your whole group, so there is no need to divide the pupils between separate spaces.`, 'The group should eat lunch on the covered ______.', 'terrace', 'The covered terrace is the lunch area because garden paths are under repair.'],
      [`We have asked pupils to leave their school bags in the lockers by reception. Coats may go in the same lockers, but keep any medication with the responsible adult. Please do not leave bags along the dome aisles: those routes need to remain clear when the lighting is low and visitors are finding their seats.`, 'School bags should be left in the ______.', 'lockers', 'Bags belong in reception lockers so the dome aisles remain clear.'],
      [`The afternoon workshop focuses on shadows. Instead of giving pupils a worksheet with predictions already listed, the educator asks them to design a simple test. We want them to recognise that changing the position of the light source can be investigated systematically, with one feature changed while the others remain stable.`, 'What is the main purpose of the afternoon workshop?', 'To practise designing a controlled test', 'Pupils design a test that changes one feature while keeping others stable.', ['To memorise the names of stars', 'To practise designing a controlled test', 'To complete a drawing competition']],
      [`Photography is welcome in the discovery room, provided no flash is used. It is not allowed inside the dome because even a small phone screen distracts other visitors. Teachers can download a selection of images afterwards for classroom discussion, so you will not need to photograph every display in order to revisit the learning later.`, 'Photography is permitted in the discovery room without ______.', 'flash', 'Photography is allowed there only without flash.'],
      [`Before leaving, collect the teacher's resource pack from the education desk. It includes activities suitable for a cloudy day, when outdoor observations might be impossible. We prepared it after teachers told us that lessons often had to be cancelled or postponed simply because their planned work depended on seeing the Sun or stars directly.`, 'The resource pack includes activities suitable for a ______ day.', 'cloudy', 'The pack includes alternatives for cloudy days when direct sky observation is difficult.'],
      [`Finally, your coach should return to the north gate at two forty-five. The main entrance is used by public buses in the afternoon and cannot accommodate a waiting coach. We will bring your group to the north gate together after everyone has collected bags and checked the discovery room for any lost belongings.`, 'The coach should collect pupils at the ______ gate.', 'north', 'The north gate is the coach collection point; public buses use the main entrance.']
    ], `If anyone needs a quiet space during the visit, let an educator know. A small room beside the education office is available. We hope pupils leave with questions of their own, as well as answers to the questions they brought with them. Now, please follow me into the discovery room.`],
    ['Designing an accessible museum guide', `Supervisor: You are developing an audio guide for the local transport museum. What have you learned from the pilot?
Sam: We tested it with six visitors who had different levels of sight.
Iris: They gave us detailed comments, and several challenged assumptions we made when writing the first version.
Supervisor: That is exactly why a pilot is useful. Tell me what you intend to change.`, [
      [`Sam: We had started every track with historical background about the exhibit.
Iris: But visitors said they first needed to know where they were standing and what was directly in front of them.
Supervisor: So begin with orientation, then move to the historical interpretation. Otherwise listeners may struggle to connect your description with the physical object.`, 'What should each track begin with?', 'Information about the listener’s position', 'Orientation should precede the historical account so listeners can locate the object.', ['A long historical introduction', 'Information about the listener’s position', 'The museum’s admission prices']],
      [`Iris: Our descriptions were also too long. Some lasted nearly five minutes.
Sam: We have agreed to limit the main track for each object to ninety seconds. Extra details can be offered through an optional second track.
Supervisor: That allows visitors to choose their depth of engagement instead of requiring everyone to hear everything.`, 'Each main object track will last no more than ______ seconds.', '90', 'The main track will be limited to ninety seconds, with optional additional detail.', null, ['ninety']],
      [`Sam: We thought background music would make the guide more engaging.
Iris: Two participants found that it masked parts of the narration, particularly near the noisy engine display.
Supervisor: Remove the music from the descriptions. If you include a historical sound, present it separately and explain what it is before playing it.`, 'Why will background music be removed?', 'It made the narration harder to hear', 'Participants reported that music masked spoken descriptions.', ['It was too expensive to record', 'It made the narration harder to hear', 'It was historically inaccurate']],
      [`Iris: Several people asked whether they could touch anything. We had assumed that was outside our project.
Supervisor: It is relevant to the visitor experience. Ask the curator which objects are robust enough for supervised handling.
Sam: The curator has already offered a replica steering wheel, so we can incorporate that into one stop.`, 'The curator has offered a replica ______ for handling.', 'steering wheel', 'A replica steering wheel will provide a tactile element.'],
      [`Sam: We originally used instructions such as “turn towards the large window”.
Iris: That was unhelpful for someone who could not see the window.
Supervisor: Use directions based on the listener's current position, supported by consistent landmarks that can be detected without sight. Test the instructions in the room rather than judging them only on paper.`, 'What was the problem with some original directions?', 'They depended on being able to see', 'Directions referencing a visible window were unsuitable for visitors unable to locate it visually.', ['They depended on being able to see', 'They included too many distances', 'They used outdated street names']],
      [`Iris: One participant wanted a printed transcript for a companion who preferred reading.
Sam: We can provide that in large print as well as standard text.
Supervisor: Good. Do not assume one format serves everyone in a group. A transcript also allows visitors to check a name or revisit a detail without replaying an entire recording.`, 'A large-print ______ will accompany the audio guide.', 'transcript', 'The audio will be supported by a transcript in large print and standard text.'],
      [`Sam: Should we ask the same six people to test the revised version?
Supervisor: Invite some back, but include new visitors too. Returning participants can tell you whether their concerns were addressed. New participants reveal difficulties that experienced testers might overlook because they already know the route and the order of the exhibits.`, 'Who should take part in the next trial?', 'A mixture of returning and new visitors', 'Returning users assess improvements, while new users can reveal unfamiliarity-related problems.', ['Only the original six participants', 'Only museum employees', 'A mixture of returning and new visitors']],
      [`Iris: For the next trial, I will observe the route while Sam takes notes afterwards.
Supervisor: Record any requests for assistance during the visit as well. Those are useful indicators of where the guide is unclear.
Sam: We will put a simple checklist on a clipboard so the observer can record events without interrupting the visitor.`, 'The observer will use a ______ to record requests for assistance.', 'checklist', 'A checklist will capture assistance requests during the visit.'],
      [`Sam: We have space for only ten stops in the prototype. Should we select the most famous vehicles?
Iris: I would prefer examples that offer different materials, shapes and stories.
Supervisor: I agree with Iris. A varied selection will test the approach more thoroughly than ten very similar objects, even if all ten are popular exhibits.`, 'How should the prototype’s exhibits be selected?', 'To provide a varied set of experiences', 'The supervisor supports variety of materials, shapes and stories for a better test.', ['By their monetary value', 'By their popularity alone', 'To provide a varied set of experiences']],
      [`Iris: The museum can host the next trial in the first week of June.
Supervisor: Book a morning session. The galleries become busier after lunch, and you need a relatively quiet setting to identify problems in the instructions themselves. Later, you can assess how the guide performs under more demanding conditions.
Sam: I will arrange that today.`, 'The next trial should take place during the ______.', 'morning', 'A morning trial offers a quieter setting for checking the revised instructions.']
    ], `Supervisor: Remember to ask permission before recording anyone's comments, and keep the report focused on usability rather than identifying individual participants.
Iris: We will use participant numbers in our notes.
Sam: Then our next tasks are to revise the scripts, prepare the transcript and confirm the trial arrangements.`],
    ['Collecting water from coastal fog', `In this lecture we will examine fog collection as one possible source of water in some coastal environments. It is not a universal solution to water scarcity. Success depends on local weather, suitable sites and regular maintenance. I will use an imagined field project to show how a community might evaluate the method before deciding whether to expand it.`, [
      [`Fog consists of tiny liquid droplets suspended in air. When wind carries these droplets through a mesh screen, some strike the fibres and join together. Once the combined droplets are large enough, gravity draws them down towards a channel at the bottom. The system collects existing liquid water rather than manufacturing water from dry air.`, 'Fog droplets are captured by a ______ screen.', 'mesh', 'Wind-blown liquid droplets strike and collect on a mesh screen.'],
      [`The field team began by measuring conditions along several ridges. The highest location was not automatically the best. One summit often stood above the fog layer, while a lower ridge was regularly immersed in it. The team therefore placed small trial collectors at several elevations instead of selecting the tallest hill simply from a map.`, 'Why was the highest summit not chosen automatically?', 'It was sometimes above the fog layer', 'The summit could be above the fog, while a lower ridge remained immersed.', ['It was too close to houses', 'It was sometimes above the fog layer', 'It received too much rainfall']],
      [`Each trial collector faced the prevailing wind. The researchers recorded wind direction as well as water yield because a screen facing the wrong way might give a misleading impression of a site's potential. At locations where the wind changed direction frequently, they compared more than one orientation before interpreting the collection totals.`, 'Trial collectors were positioned to face the prevailing ______.', 'wind', 'The screens faced the prevailing wind to intercept wind-blown fog droplets.'],
      [`Water running down the mesh entered a narrow gutter and then travelled through a pipe to a covered tank. The cover reduced contamination from leaves, insects and wind-blown debris. It did not by itself make the water suitable for drinking; quality testing and any necessary treatment remained separate requirements in the project plan.`, 'Collected water passed through a pipe into a covered ______.', 'tank', 'A covered tank stored the collected water while reducing entry of debris.'],
      [`The first comparison involved two mesh materials. One captured more water in light winds but tore more easily during storms. The other produced slightly less water but survived rough conditions better. The team calculated performance over the full season, recognising that a damaged collector produces nothing while waiting for replacement material to arrive.`, 'What did the mesh comparison show?', 'Durability mattered as well as immediate yield', 'A high-yielding mesh was vulnerable to storm damage, making seasonal reliability important.', ['The most delicate mesh always performed best', 'Durability mattered as well as immediate yield', 'Both materials collected identical amounts']],
      [`Maintenance included clearing the gutters and checking the tension of the supporting cables. Loose cables allowed the mesh to flap, which increased wear around its attachment points. Local residents were trained to make these checks, because relying on a visiting specialist for every small repair would create delays and increase the running costs.`, 'Maintenance workers checked the tension of the supporting ______.', 'cables', 'Cable tension was checked to prevent damaging movement of the mesh.'],
      [`The team kept a daily log for six months. Reporting only the best day would have exaggerated the system's usefulness. Some weeks produced substantial water, while others yielded very little. Plotting the daily values revealed the length of dry intervals and helped estimate how much storage would be needed to bridge them.`, 'The team maintained a daily log for ______ months.', '6', 'Daily records were kept for six months, rather than reporting only peak output.', null, ['six']],
      [`Residents initially proposed using the collected water for every household purpose. After reviewing the variable supply, they selected a more limited first use: irrigating a tree nursery. This matched the available volume and provided a manageable trial. Any future drinking-water use would require additional planning, reliable treatment and continuing checks of water quality.`, 'The first planned use of the collected water was irrigation of a ______.', 'tree nursery', 'The community chose to irrigate a tree nursery as a manageable first application.'],
      [`The researchers also considered access. A ridge with excellent collection results required a long walk across unstable ground, making repairs difficult. A slightly less productive site near an existing track was preferred for the next phase. This decision illustrates why a technically impressive yield is only one part of a workable community system.`, 'The preferred expansion site was close to an existing ______.', 'track', 'Access by an existing track made maintenance more practical despite a slightly lower yield.'],
      [`Finally, the project established a maintenance fund before expanding the installation. Contributions were intended to cover replacement mesh, pipes and small tools. The researchers emphasised that the equipment was simple, but not free to operate forever. Agreeing who would organise repairs was as important as deciding where the next set of collectors should stand.`, 'A maintenance ______ was established to pay for repairs and replacement materials.', 'fund', 'A maintenance fund covered ongoing repair and replacement costs.']
    ], `The lesson is that fog collection should be assessed as a local system, not just as a piece of equipment. Weather measurements, water quality, storage, access and community organisation all influence its value. A careful trial can identify a useful role while preventing unrealistic expectations about what the method can deliver.`]
  ]);
  add(7, 'Music, media and materials', [
    ['Hiring an instrument', `Assistant: Hello, Westgate Music Hire. What can I do for you?
Parent: My daughter is starting cello lessons, and her teacher suggested renting an instrument initially. I do not know much about string instruments, so I would appreciate some advice.
Assistant: Of course. Renting is a useful way to find out what suits her before buying. Let us work through the details.`, [
      [`Assistant: Has the teacher recommended a size?
Parent: She tried a half-size instrument, but the teacher thought a three-quarter-size one would be better. My daughter has quite long arms.
Assistant: I will reserve a three-quarter-size cello, then. We can check the fit when she comes in rather than relying entirely on her age or height.`, 'The teacher recommends a ______ cello.', 'three-quarter-size', 'The teacher preferred a three-quarter-size cello to the half-size one.', null, ['three-quarter', 'three quarter', '3/4', '¾']],
      [`Parent: What is the monthly rental charge?
Assistant: Thirty-two pounds, including a bow and a protective case. The smaller cello costs twenty-seven pounds, but that is not the size you need. We inspect the instrument before collection and note its condition so there is a clear record for both of us.`, 'The monthly hire charge is £______.', '32', 'The recommended cello costs thirty-two pounds per month.', null, ['32.00', 'thirty-two', 'thirty two']],
      [`Parent: Is there a minimum rental period? I do not want to commit for a whole year.
Assistant: The minimum is three months. After that, you can continue month by month. We ask for notice before the next payment date, and the agreement explains how to return the instrument if lessons stop.`, 'The minimum rental period is ______ months.', '3', 'The minimum agreement is three months, followed by monthly renewal.', null, ['three']],
      [`Parent: Do we pay a deposit as well?
Assistant: Yes, eighty pounds, refundable when the instrument and accessories are returned in the agreed condition. Ordinary wear is expected, but accidental damage is handled separately. I will show you the relevant terms before you sign, so you know exactly what the arrangement covers.`, 'The refundable deposit is £______.', '80', 'The deposit is eighty pounds, separate from monthly hire.', null, ['eighty', '80.00']],
      [`Parent: Can we collect it this Saturday?
Assistant: The technician will finish checking it on Friday afternoon, so Saturday is fine. I can book you an appointment at ten forty-five. We set aside time to adjust the instrument and explain its care rather than handing it over at a crowded counter.`, 'The collection appointment is at ______ on Saturday.', '10:45', 'The assistant books collection for ten forty-five on Saturday.', null, ['10.45', 'ten forty-five', 'ten forty five']],
      [`Assistant: Please bring your daughter's teacher's note. It includes useful information about the recommended size and any accessories the teacher prefers.
Parent: She emailed it to me yesterday.
Assistant: Showing the email is fine. You do not need to print it, but make sure you can open it while you are in the shop.`, 'The parent should bring the teacher’s ______.', 'note', 'The teacher’s note can be shown as an email.'],
      [`Parent: Is the music stand included in the rental?
Assistant: No. The instrument, bow and case are included, but a stand is a separate purchase. You may already have one at home. It should be adjustable so your daughter can see the music comfortably without leaning forward while she plays.`, 'A ______ must be bought separately if the family does not already have one.', 'music stand', 'The rental includes the instrument, bow and case, but not a music stand.'],
      [`Parent: We are coming by car. Is there parking outside?
Assistant: The spaces directly outside are for deliveries. Use the car park behind the library; the first hour is free. There is a short level path from there to our rear door, which will be helpful when you carry the cello back.`, 'The recommended car park is behind the ______.', 'library', 'The assistant recommends the car park behind the library, not the delivery spaces.'],
      [`Assistant: We include a free check after the first six weeks. New players sometimes find that the setup needs a small adjustment once they have had a few lessons.
Parent: Should I arrange that now?
Assistant: We will book it when you collect the cello, after you know which days fit around her lessons.`, 'The free follow-up check takes place after ______ weeks.', '6', 'A free check is offered after six weeks of use.', null, ['six']],
      [`Parent: If there is a problem before then, should I ask the teacher to repair it?
Assistant: Please contact us first, ideally by email with a photograph of the problem. We can then decide whether it needs to come in. Do not arrange outside repairs without checking, because the instrument remains part of our rental stock.`, 'An email about a problem should ideally include a ______.', 'photograph', 'A photograph helps the shop assess a problem before deciding on the next step.', null, ['photo']]
    ], `Parent: Thank you. I will bring my daughter and the teacher's note on Saturday.
Assistant: We look forward to seeing you. I will send a summary of the costs and appointment time now so you can read everything before coming in.`],
    ['Community radio open day', `Hello everyone, and welcome to Harbour Community Radio. This open day is for people interested in volunteering, whether or not they have broadcasting experience. We produce local programmes from these modest studios, but many of our volunteers work away from the microphone. Today you will see several roles and have a chance to try short practical activities.`, [
      [`We begin with a tour of the newsroom upstairs. People often expect us to start in the main studio, but a live interview is taking place there until ten thirty. The newsroom tour will show how local stories are checked and prepared before anyone sits at a microphone to discuss them on air.`, 'The tour begins in the upstairs ______.', 'newsroom', 'The tour starts in the newsroom while a live interview occupies the main studio.'],
      [`Please wear the orange visitor badge you received at reception. Volunteers normally wear green badges, and staff wear blue ones. The different colours help us see who may need directions or an explanation of unfamiliar equipment. They are not a ranking system: visitors are welcome to ask questions of anyone working here today.`, 'Visitors should wear an ______ badge.', 'orange', 'Orange badges identify visitors; green and blue identify volunteers and staff.'],
      [`At eleven, you can choose between an editing demonstration and a short interview workshop. The workshop is in room four, beside the kitchen. You will work in pairs and practise asking questions that invite a detailed answer rather than a simple yes or no. There is no requirement to record your conversation.`, 'The interview workshop takes place in room ______.', '4', 'The workshop is in room four beside the kitchen.', null, ['four']],
      [`The editing demonstration uses a recording of a local walking group. Our producer will show how removing a pause can improve clarity, but also how careless editing can change a speaker's meaning. The central lesson is responsibility: technical speed matters less than preserving what the interviewee actually intended to communicate.`, 'What is the main message of the editing demonstration?', 'Editing must preserve the speaker’s meaning', 'The demonstration prioritises faithful meaning over technical speed.', ['Every pause should be removed', 'Editing must preserve the speaker’s meaning', 'Music is essential in every interview']],
      [`If you would like to try presenting, put your name on the sheet outside studio two. Each person gets five minutes to read a short announcement and listen back privately. These practice recordings will not be broadcast. We want people to experiment without feeling that their first attempt is being judged by a public audience.`, 'Each practice presenting session lasts ______ minutes.', '5', 'Each visitor has five minutes for a private presenting exercise.', null, ['five']],
      [`We also need volunteers to maintain our events calendar. That work involves contacting organisers to confirm details, not simply copying advertisements from social media. Dates and venues can change, and an inaccurate announcement can send listeners to the wrong place. People who enjoy careful checking often find this role particularly satisfying.`, 'Calendar volunteers must contact event ______ to confirm details.', 'organisers', 'Organisers should confirm event details before they are announced.', null, ['organizers']],
      [`Our next introductory training course starts in February. The January course is already full, although anyone who has registered will keep their place. The February sessions run on Wednesday evenings for four weeks, covering basic recording, interviewing, programme planning and the station's editorial standards. You must attend all four before working independently.`, 'The next available introductory course begins in ______.', 'February', 'January is full; February is the next available course.'],
      [`No expensive equipment is needed to join. We lend portable recorders for approved assignments and provide instruction in their use. A phone can be useful for making initial notes, but you should not assume that a personal recording app is appropriate for every task, especially where consent and secure handling of recordings are important.`, 'For approved assignments, volunteers can borrow portable ______.', 'recorders', 'The station lends portable recorders and provides training.'],
      [`During lunch, three volunteers will describe their first year at the station. We selected people in different roles so you can hear how their expectations changed. One began as a presenter and discovered a preference for researching stories; another expected to work alone but found that collaborative planning was the most enjoyable part.`, 'Why were three different volunteers chosen for the lunchtime discussion?', 'To show a range of experiences', 'Different roles and changing expectations will illustrate the range of volunteering experiences.', ['To announce competition winners', 'To show a range of experiences', 'To recruit only experienced presenters']],
      [`Before leaving, please return your badge to reception and complete the interest form if you would like us to contact you. The form asks which roles appeal to you, but it is not a binding commitment. We will arrange an informal conversation before either you or the station decides on a regular role.`, 'Visitors who want further contact should complete an ______.', 'interest form', 'The interest form requests follow-up contact without committing the visitor to a role.']
    ], `Refreshments are available in the kitchen throughout the morning. Please keep drinks away from the mixing desks and recording equipment. If you need to leave early, let reception know so we can account for everyone in the building. We are glad you have come, and we hope the day makes community radio feel approachable.`],
    ['Testing reusable delivery packaging', `Tutor: You have brought the results from your reusable packaging experiment. How did the trial go?
Lena: We tested three designs for delivering ceramic mugs to local customers.
Arun: We expected protection to be the main challenge, but collecting the empty packaging turned out to matter just as much.
Tutor: That is useful. Explain the design of the trial before describing your findings.`, [
      [`Lena: We wanted to compare packaging materials, so every parcel contained the same type of mug.
Arun: We also used the same delivery route. Otherwise a design might look safer simply because it travelled a shorter distance over smoother roads.
Tutor: Good. Keeping those conditions consistent makes the comparison easier to interpret.`, 'Why did the students use the same delivery route?', 'To make the comparison fairer', 'Using the same route controlled differences in distance and road conditions.', ['To make the comparison fairer', 'To avoid collecting any data', 'To test different vehicle sizes']],
      [`Arun: Each design was used for twelve deliveries. We had planned fifteen, but there was not enough time to inspect and reset every package properly.
Lena: Rather than rush those checks, we reduced the number equally for all three designs.
Tutor: Make that adjustment clear in your methods section, including the reason for it.`, 'Each packaging design was tested on ______ deliveries.', '12', 'Each design had twelve deliveries, reduced equally from the planned fifteen.', null, ['twelve']],
      [`Lena: The rigid box protected the mugs best, but customers found it awkward to store until collection.
Arun: The folding design was slightly less convenient for us to assemble, yet customers could flatten it after unpacking.
Tutor: That suggests the best design for the sender may not be the best for the recipient.`, 'What advantage did customers identify in the folding design?', 'It took less space after unpacking', 'Customers could flatten the folding design while waiting for collection.', ['It arrived more quickly', 'It took less space after unpacking', 'It required no assembly by the sender']],
      [`Arun: We initially measured only the time needed to pack each mug.
Lena: Then we added cleaning time after the package was returned. Some designs had narrow corners that were difficult to wipe.
Tutor: Including cleaning gives you a more complete view of repeated use. A quick packing process can be offset by slow preparation for the next delivery.`, 'The students added ______ time to their measurements after packages were returned.', 'cleaning', 'Cleaning time was added to the original packing-time measure.'],
      [`Lena: We were surprised that several packages were not ready on the agreed collection day.
Arun: We assumed customers had forgotten, but their comments suggested our instructions were unclear about whether collection was automatic.
Tutor: So the problem may be communication rather than unwillingness to return the packaging. You should test clearer instructions before drawing a broader conclusion.`, 'What may explain the missed collections?', 'Unclear return instructions', 'Customers did not understand whether collection happened automatically.', ['Customers disliked the mugs', 'The packages were too heavy to lift', 'Unclear return instructions']],
      [`Arun: For the next trial, we will put a return label inside each package, visible as soon as it is opened.
Lena: It will give the collection date and explain how to request a different time.
Tutor: Keep the wording short and test it with someone who has not heard your explanation of the project.`, 'The revised instructions will appear on a ______ inside each package.', 'return label', 'A return label will state the collection date and rescheduling method.'],
      [`Lena: Should we describe the folding design as environmentally friendly because customers preferred it?
Tutor: Preference alone does not establish an environmental benefit. You would need information about manufacture, cleaning, transport and the number of times each package is actually reused.
Arun: Then we will report user preference separately from any claims about environmental performance.`, 'What does the tutor say about environmental claims?', 'They require evidence beyond user preference', 'Environmental performance depends on manufacture, cleaning, transport and reuse, not preference alone.', ['Customer preference is sufficient evidence', 'They require evidence beyond user preference', 'Reusable designs always have zero impact']],
      [`Arun: We have photographs showing damage to the corners after repeated trips.
Lena: A table might make it easier to compare the designs, though.
Tutor: Use both, but give them distinct purposes. Summarise the frequency of damage in a table and use selected photographs to show what the categories of damage actually mean.`, 'The frequency of damage will be summarised in a ______.', 'table', 'The table will compare frequencies, while photographs illustrate damage categories.'],
      [`Lena: For a longer study, we would recruit more customers immediately.
Tutor: First make sure your return process works reliably with the existing group. Increasing the sample would create more data, but it might simply repeat an avoidable weakness in the procedure.
Arun: So we should revise the instructions, run a small check, and then expand.`, 'What should happen before the study is expanded?', 'The return procedure should be improved', 'The tutor recommends fixing the return process before increasing the sample.', ['The return procedure should be improved', 'All cleaning measurements should be removed', 'Only the strongest box should be tested']],
      [`Arun: We can bring the revised return label to our next meeting on Monday.
Tutor: Send it by Friday so I can read it beforehand. Then Monday's meeting can focus on your overall report rather than spending most of the time editing a short notice.
Lena: We will send the wording and a photograph of its position inside the box.`, 'The revised label should be sent to the tutor by ______.', 'Friday', 'The tutor requests the label by Friday, before Monday’s meeting.']
    ], `Tutor: Your project is strongest when it connects the physical design with the way people use it. Keep that connection clear in the report.
Lena: We will organise the discussion around protection, handling and return.
Arun: And distinguish our measured results from the questions that need a larger study.`],
    ['Following sediment through a river system', `Today we will consider how researchers follow the movement of sediment through a river system. Sediment includes particles of different sizes, from fine material suspended in water to larger stones moved along the bed. I will describe a fictional catchment study to illustrate why a single measurement at one point cannot explain everything happening along a river.`, [
      [`The project began with a map of the catchment, meaning the area of land that drains into the river and its tributaries. Researchers marked likely sources of sediment, including exposed soil, eroding banks and construction areas. This helped them choose sampling locations that could reveal differences between incoming material and what was already stored within the channel.`, 'The area draining into the river is called the ______.', 'catchment', 'The catchment includes the land draining into the river and its tributaries.'],
      [`At three bridges, the team installed sensors to record turbidity, a measure related to how cloudy the water is. These sensors provided frequent readings, but they did not directly weigh the sediment. Water samples were therefore collected alongside sensor measurements so the researchers could compare the optical readings with the amount of suspended material in the samples.`, 'Sensors at the bridges recorded water ______.', 'turbidity', 'Turbidity readings were compared with physical water samples.'],
      [`Sampling only in calm weather would have missed important events. During heavy rain, more water ran over exposed ground and carried particles into streams. The team used automatic samplers triggered by a rise in water level, allowing them to collect information during short events that might occur overnight when no researcher was present.`, 'Automatic samplers were triggered by a rise in water ______.', 'level', 'Rising water level triggered sampling during events, including overnight storms.'],
      [`The researchers found that the highest sediment concentration did not always occur at the highest water level. At one site, readily available material was washed into the river early in a storm. Later, the flow continued to rise but carried a lower concentration because much of that easily moved material had already been removed.`, 'Why could sediment concentration fall while water level continued rising?', 'Easily moved material had already been washed away', 'Available loose sediment was flushed early, leaving less to transport later.', ['The river stopped flowing', 'Easily moved material had already been washed away', 'All the sensors were switched off']],
      [`To investigate larger particles, the team marked a small number of pebbles with identification tags. They recorded the starting position of each pebble and searched for it after selected high-flow events. This did not track every stone in the river, but it showed that movement could occur in steps, with long periods of rest between them.`, 'Selected pebbles were fitted with identification ______.', 'tags', 'Identification tags allowed the researchers to locate selected pebbles after high flows.'],
      [`Some tagged pebbles accumulated behind fallen branches. These temporary barriers slowed local flow and created places where sediment could settle. When a later flood moved the branches, some of the stored material travelled downstream again. The findings reminded the team that a river channel is both a transport route and a changing store of material.`, 'Fallen ______ created temporary places where pebbles accumulated.', 'branches', 'Fallen branches slowed local flow and trapped some pebbles temporarily.'],
      [`The study also compared samples from two tributaries. Their sediment had different mineral characteristics, which helped the team estimate their contributions farther downstream. The method was not exact because particles from different sources could overlap in composition. Researchers reported uncertainty rather than assigning every grain confidently to a particular hillside or stream.`, 'What limitation affected the comparison of sediment sources?', 'Different sources could have overlapping characteristics', 'Mineral composition could overlap, so source attribution was uncertain.', ['No samples could be collected', 'Different sources could have overlapping characteristics', 'The tributaries contained no sediment']],
      [`At a small reservoir, repeated depth surveys showed where material had settled. The team compared the new measurements with an earlier survey, taking care to use the same reference level. Differences in water height alone could otherwise be mistaken for changes in the reservoir bed, producing an inaccurate estimate of accumulated sediment.`, 'Reservoir depth surveys had to use the same reference ______.', 'level', 'A common reference level prevented water-height differences from being confused with bed changes.'],
      [`When discussing management, the researchers avoided recommending that all sediment be trapped upstream. Sediment can create habitats and replenish material downstream, so removing it indiscriminately may introduce new problems. Their first recommendation was to reduce avoidable erosion from bare construction ground while continuing to study the natural movement of material through the catchment.`, 'The first management recommendation targeted erosion from bare ______ ground.', 'construction', 'The team targeted avoidable erosion at construction areas rather than trapping all sediment.'],
      [`Finally, the project shared results with local landowners through an illustrated seasonal report. A single annual total would have hidden the timing of the largest changes. Showing when sediment moved helped residents connect observations with particular storms and land activities, creating a more useful discussion about where practical improvements might be possible.`, 'Results were shared with landowners in an illustrated ______ report.', 'seasonal', 'A seasonal report showed the timing of sediment movement, not only an annual total.']
    ], `The overall message is that sediment moves unevenly in both space and time. Some particles travel quickly; others remain stored for years before moving again. Combining continuous measurements, physical samples and repeated surveys gives a more informative picture than relying on any one technique by itself.`]
  ]);
  window.TicketListeningExtraA = bank;
})();
